/** Emscripten module factory generated by `./build.sh` (w-synth.js). */
export interface WSynthModule {
	HEAPU8: Uint8Array;
	cwrap(
		name: string,
		returnType: 'number' | 'boolean' | null,
		argTypes: ('number' | 'boolean')[]
	): (...args: number[]) => number;
	getValue(ptr: number, type: 'i32' | 'i8' | 'float' | 'double'): number;
	_malloc(size: number): number;
	_free(ptr: number): void;
}

export interface WSynthModuleOptions {
	instantiateWasm?: (
		imports: WebAssembly.Imports,
		receive: (instance: WebAssembly.Instance, module: WebAssembly.Module) => void
	) => unknown;
	print?: (line: string) => void;
	printErr?: (line: string) => void;
}

declare const factory: (options?: WSynthModuleOptions) => Promise<WSynthModule>;
export default factory;
